package com.xianshuyuan.scm.purchase.controller;
import com.xianshuyuan.scm.common.api.ApiResponse; import com.xianshuyuan.scm.purchase.dto.*; import com.xianshuyuan.scm.purchase.entity.PurchaseDemandEntity; import com.xianshuyuan.scm.purchase.service.PurchaseDemandService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/purchase-demands") public class PurchaseDemandController { private final PurchaseDemandService service; public PurchaseDemandController(PurchaseDemandService s){service=s;} @GetMapping public ApiResponse<List<PurchaseDemandEntity>> list(){return ApiResponse.success(service.list());} @GetMapping("/{id}") public ApiResponse<PurchaseDemandEntity> get(@PathVariable long id){return ApiResponse.success(service.get(id));} @PostMapping("/generate") public ApiResponse<List<Long>> generate(@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody PurchaseDemandGenerateRequest r){return ApiResponse.success(service.generate(r,key));} @PostMapping("/allocate") public ApiResponse<Void> allocate(@Valid @RequestBody PurchaseDemandAllocationRequest r){service.allocate(r);return ApiResponse.success(null);} }
